	topic_name VARCHAR(100) NOT NULL,
	description VARCHAR(500),
	sort_order INTEGER DEFAULT '0' NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	is_active BOOLEAN,
	CONSTRAINT pk_topic PRIMARY KEY (topic_id),
	CONSTRAINT uq_topic_topic_code UNIQUE (topic_code)
);

CREATE TABLE topic_cluster (
	topic_cluster_id BIGSERIAL NOT NULL,
	representative_content_id BIGINT,
	subtopic_id BIGINT,
	cluster_title VARCHAR(300),
	cluster_summary TEXT,
	member_count INTEGER DEFAULT '0' NOT NULL,
	centroid_vector VECTOR,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	CONSTRAINT pk_topic_cluster PRIMARY KEY (topic_cluster_id)
);

CREATE TABLE user_account (
	user_id BIGSERIAL NOT NULL,
	provider_user_id VARCHAR(255),
	email VARCHAR(255),
	nickname VARCHAR(50) NOT NULL,
	account_status VARCHAR(20) DEFAULT 'active' NOT NULL,
	auth_provider VARCHAR(20) DEFAULT 'local' NOT NULL,
	hashed_password VARCHAR(255),
	profile_image_url VARCHAR(500),
	last_login_at TIMESTAMP WITH TIME ZONE,
	onboarding_completed_at TIMESTAMP WITH TIME ZONE,
	joined_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	withdrawn_at TIMESTAMP WITH TIME ZONE,
	withdrawal_reason TEXT,
	CONSTRAINT pk_user_account PRIMARY KEY (user_id),
	CONSTRAINT uq_user_account_auth_provider_provider_user_id UNIQUE (auth_provider, provider_user_id),
	CONSTRAINT ck_user_account_status CHECK (account_status IN ('active', 'warned', 'suspended', 'banned', 'withdrawn')),
	CONSTRAINT ck_user_account_auth_provider CHECK (auth_provider IN ('local', 'kakao', 'naver', 'apple')),
	CONSTRAINT ck_user_account_auth_identity CHECK ((auth_provider = 'local' AND email IS NOT NULL AND hashed_password IS NOT NULL AND provider_user_id IS NULL) OR (auth_provider <> 'local' AND provider_user_id IS NOT NULL))
);

CREATE TABLE user_event (
	user_event_id BIGSERIAL NOT NULL,
	client_event_id UUID NOT NULL,
	user_id BIGINT NOT NULL,
	tap_id BIGINT NOT NULL,
	event_type VARCHAR(30) NOT NULL,
	content_id BIGINT NOT NULL,
	recommendation_item_id BIGINT,
	event_value JSONB DEFAULT '{}'::jsonb NOT NULL,
	occurred_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	received_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	data_source VARCHAR(20) NOT NULL,
	CONSTRAINT pk_user_event PRIMARY KEY (user_event_id),
	CONSTRAINT uq_user_event_client_event_id UNIQUE (client_event_id),
	CONSTRAINT ck_user_event_type CHECK (event_type IN ('impression', 'open', 'like', 'like_cancel', 'bookmark', 'bookmark_cancel', 'preference_positive', 'preference_negative', 'preference_cancel', 'card_swipe', 'share', 'spoiler_reveal', 'watched')),
	CONSTRAINT ck_user_event_data_source CHECK (data_source IN ('production', 'local_demo', 'automated_test', 'imported'))
);

CREATE TABLE user_operation (
	operation_id UUID NOT NULL,
	user_id BIGINT NOT NULL,
	operation_type VARCHAR(30) NOT NULL,
	resource_id BIGINT NOT NULL,
	status VARCHAR(20) DEFAULT 'queued' NOT NULL,
	error_code VARCHAR(50),
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	completed_at TIMESTAMP WITH TIME ZONE,
	CONSTRAINT pk_user_operation PRIMARY KEY (operation_id),
	CONSTRAINT ck_user_operation_type CHECK (operation_type IN ('chat_deletion')),
	CONSTRAINT ck_user_operation_status CHECK (status IN ('queued', 'processing', 'completed', 'failed'))
);

